// All money fields are KRW 100 million (억원); returns are percentages.
export const ACTORS={pension:'연기금',foreign:'외국인',trust:'투신',private:'사모펀드',financial:'금융투자',insurance:'보험',bank:'은행',other_institution:'기타 기관'};
export const DEFAULTS={minAmount:0,minCap:0,minTurnover:0,minBuyDays:3,acceleration:0,divergence:0,passiveVolume:2};
export const SIGNALS={A:'연기금 신규 매집',FN:'외국인 신규 매집',B:'동반 매집',C:'잠재적 수급 괴리',D:'외국인 매수 가속',E:'수급 이탈 경고',F:'패시브 수급 의심'};
export const finite=v=>typeof v==='number'&&Number.isFinite(v);
export const total=(rows,key)=>rows.length&&rows.every(r=>finite(r[key]))?rows.reduce((s,r)=>s+r[key],0):null;
export const price=r=>finite(r?.adjusted_close)?r.adjusted_close:r?.close;
export function relative(p0,p1,b0,b1){return [p0,p1,b0,b1].every(v=>finite(v)&&v>0)?((p1/p0)/(b1/b0)-1)*100:null;}
export const ratio=(n,d)=>finite(n)&&finite(d)&&d>0?n/d*100:null;
// Calendar periods are anchored to the dataset's last date, not today's clock.
export function selectChartRows(rows, period='3M') {
 if(!rows.length)return {rows:[],complete:false,requestedStart:null};
 if(/^\d+$/.test(String(period))){let n=Number(period);return {rows:rows.slice(-n),complete:rows.length>=n,requestedStart:null};}
 const end=rows.at(-1).date, date=new Date(end+'T00:00:00Z');let target;
 if(period==='YTD')target=(date.getUTCFullYear()-1)+'-12-31';
 else {let months={'3M':3,'6M':6,'1Y':12}[period];if(!months)throw Error('지원하지 않는 차트 기간');
  let day=date.getUTCDate();date.setUTCDate(1);date.setUTCMonth(date.getUTCMonth()-months);
  let lastDay=new Date(Date.UTC(date.getUTCFullYear(),date.getUTCMonth()+1,0)).getUTCDate();date.setUTCDate(Math.min(day,lastDay));target=date.toISOString().slice(0,10);}
 let baseline=-1;for(let i=0;i<rows.length&&rows[i].date<=target;i++)baseline=i;
 return {rows:rows.slice(Math.max(0,baseline)),complete:baseline>=0,requestedStart:target};
}
export function windowSum(rows,k,n){return rows.length>=n?total(rows.slice(-n),k):null;}
export function streak(rows,k){if(!finite(rows.at(-1)?.[k]))return null;if(rows.at(-1)[k]===0)return 0;let sign=Math.sign(rows.at(-1)[k]),n=0;for(let i=rows.length-1;i>=0&&finite(rows[i][k])&&Math.sign(rows[i][k])===sign;i--)n++;return n*sign;}
export function actorMetrics(rows,k){let last=rows.at(-1),out={today:last?.[k]??null,streak:streak(rows,k)};for(let n of [5,10,20,60]){let amount=windowSum(rows,k,n),slice=rows.slice(-n);out[n]={amount,cap:ratio(amount,last?.marketcap),turnover:ratio(amount,total(slice,'turnover'))};}let s=rows.slice(-20);out.buyDays=rows.length>=20&&s.every(r=>finite(r[k]))?s.filter(r=>r[k]>0).length:null;let p=rows.slice(-20,-5);out.acceleration=rows.length>=20&&total(p,k)!==null&&out[5].amount!==null?out[5].amount/5-total(p,k)/15:null;return out;}
export function cumulative(rows,k){let s=0,gap=false;return rows.map((r,i)=>{if(i===0)return 0;if(!finite(r[k]))gap=true;if(gap)return null;return s+=r[k]});}
export function movingAverage(rows,n){return rows.map((r,i)=>i<n-1?null:rows.slice(i-n+1,i+1).reduce((s,v)=>s+price(v),0)/n);}
export function analyze(rows,settings=DEFAULTS,benchmark='benchmark'){const cfg={...DEFAULTS,...settings},last=rows.at(-1),actors=Object.fromEntries(Object.keys(ACTORS).map(k=>[k,actorMetrics(rows,k)]));let p=actors.pension,f=actors.foreign;let rel20=rows.length>=21?relative(price(rows.at(-21)),price(last),rows.at(-21)[benchmark],last[benchmark]):null;let signals=[],turn=total(rows.slice(-5),'turnover');const strong=(a)=>[a[5].amount,a[5].cap,a[5].turnover].every(finite)&&a[5].amount>cfg.minAmount&&a[5].cap>=cfg.minCap&&a[5].turnover>=cfg.minTurnover;
for(let [k,sig] of [['pension','A'],['foreign','FN']]){let a=actors[k],prev=rows.length>=25?total(rows.slice(-25,-5),k):null,buy5=rows.slice(-5).filter(r=>r[k]>0).length;if(prev!==null&&prev<0&&strong(a)&&buy5>=cfg.minBuyDays)signals.push(sig);}
if(strong(p)&&strong(f)&&p[20].amount>0&&f[20].amount>0)signals.push('B');
if(rel20!==null&&rel20< -cfg.divergence&&[p,f].some(a=>[a[20].amount,a[20].cap,a[20].turnover].every(finite)&&a[20].amount>cfg.minAmount&&a[20].cap>=cfg.minCap&&a[20].turnover>=cfg.minTurnover))signals.push('C');
if(strong(f)&&f.acceleration>cfg.acceleration)signals.push('D');
const weak=a=>[a[5].amount,a[5].cap,a[5].turnover].every(finite)&&a[5].amount< -cfg.minAmount&&-a[5].cap>=cfg.minCap&&-a[5].turnover>=cfg.minTurnover;let exit=[['pension',p],['foreign',f]].some(([k,a])=>{let prev=rows.length>=25?total(rows.slice(-25,-5),k):null;return prev>0&&a[5].amount< -cfg.minAmount&&-a[5].cap>=cfg.minCap&&-a[5].turnover>=cfg.minTurnover});
if(exit||(weak(p)&&weak(f)))signals.push('E');
let vol20=rows.slice(-21,-1),avgVol=vol20.length===20&&vol20.every(r=>finite(r.volume))?total(vol20,'volume')/20:null,volMultiple=avgVol>0&&finite(last.volume)?last.volume/avgVol:null;
let events=rows.slice(-5).flatMap(r=>(r.events||[]).filter(e=>e.verified===true&&e.source_url&&['etf_rebalance','index_change','block_trade'].includes(e.type)).map(e=>({...e,date:r.date})));let passive=events.length?(volMultiple>=cfg.passiveVolume?'의심 · 이벤트 확인':'관련 이벤트 확인'):'미확인';if(events.length&&volMultiple>=cfg.passiveVolume)signals.push('F');
let together=0;for(let i=rows.length-1;i>=0;i--){if(rows[i].pension>0&&rows[i].foreign>0)together++;else break;}
let ownershipBase=rows.length>=21?rows.at(-21):null;let ownershipChange=finite(last.foreign_ownership)&&finite(ownershipBase?.foreign_ownership)?last.foreign_ownership-ownershipBase.foreign_ownership:null;
return{rows,last,actors,signals,rel20,volMultiple,passive,events,together,ownershipChange,dayReturn:rows.length>=2?(price(last)/price(rows.at(-2))-1)*100:null,acceleration:finite(p.acceleration)&&finite(f.acceleration)?p.acceleration+f.acceleration:null,score:null};}
export function rank(items,weights=[.30,.25,.20,.15,.10]){let fs=[m=>m.actors.pension[20].cap,m=>m.actors.foreign[20].cap,m=>ratio(m.acceleration,m.last.marketcap),m=>finite(m.actors.pension.buyDays)&&finite(m.actors.foreign.buyDays)?(m.actors.pension.buyDays+m.actors.foreign.buyDays)/40:null,m=>finite(m.rel20)?(m.signals.includes('C')?-m.rel20:0):null];let transformed=fs.map(fn=>{let vs=items.map(fn),valid=vs.filter(finite);let mean=valid.reduce((s,v)=>s+v,0)/valid.length,sd=Math.sqrt(valid.reduce((s,v)=>s+(v-mean)**2,0)/valid.length);return vs.map(v=>finite(v)?Math.max(-3,Math.min(3,sd>Math.max(1e-12,Math.abs(mean)*1e-12)?(v-mean)/sd:0)):null)});let weightSum=weights.reduce((s,v)=>s+v,0);return items.map((m,i)=>({...m,score:items.length<3||weightSum<=0||transformed.some(a=>a[i]===null)?null:50+50/3*transformed.reduce((s,a,j)=>s+a[i]*weights[j]/weightSum,0)}));}
export function validateDataset(input){if(!input||input.schema_version!==2||!input.meta||!Array.isArray(input.rows))throw Error('schema_version: 2와 meta, rows가 필요합니다.');let meta=input.meta;if(!['real','example','empty'].includes(meta.data_kind))throw Error('data_kind는 real/example/empty여야 합니다.');if(meta.unit!=='KRW_100M')throw Error('금액 단위는 KRW_100M(억원)이어야 합니다.');if(!['final','provisional','unknown','unconnected','example'].includes(meta.status))throw Error('잠정/확정 상태 오류');if(typeof meta.source!=='string'||typeof meta.benchmark_name!=='string'||!meta.source||!meta.benchmark_name||!['adjusted','raw','unknown'].includes(meta.price_basis)||![true,false,null].includes(meta.dividend_adjusted))throw Error('출처·벤치마크·가격기준·배당 반영 메타데이터를 확인하세요.');if(!meta.fetched_at||!Number.isFinite(Date.parse(meta.fetched_at)))throw Error('갱신시각이 필요합니다.');let seen=new Set(),groups=new Map();for(let r of input.rows){if(!r||typeof r.date!=='string'||typeof r.code!=='string'||typeof r.name!=='string')throw Error('행의 날짜·코드·이름은 문자열이어야 합니다.');if(!/^\d{4}-\d{2}-\d{2}$/.test(r.date)||!Number.isFinite(Date.parse(r.date))||new Date(r.date).toISOString().slice(0,10)!==r.date)throw Error('날짜 형식 오류');if(!/^\d{6}$/.test(r.code)||!r.name||(typeof r.sector!=='string'||!r.sector.trim()))throw Error('종목코드·이름·업종 오류');let id=r.date+r.code;if(seen.has(id))throw Error('날짜·종목 중복: '+id);seen.add(id);for(let k of ['close','benchmark','marketcap'])if(!finite(r[k])||r[k]<=0)throw Error(r.code+' '+r.date+' '+k+'는 양수여야 합니다.');if(!finite(r.turnover)||r.turnover<0)throw Error('거래대금 오류');if(meta.price_basis==='raw'&&finite(r.adjusted_close))throw Error('비수정 가격 기준에는 adjusted_close를 비워 주세요.');if(meta.price_basis==='adjusted'&&(!finite(r.adjusted_close)||r.adjusted_close<=0))throw Error('수정종가가 누락되었습니다.');for(let k of [...Object.keys(ACTORS),'volume','foreign_ownership','adjusted_close','sector_benchmark',...Object.keys(ACTORS).map(k=>k+'_qty')])if(r[k]!==undefined&&r[k]!==null&&!finite(r[k]))throw Error(k+' 숫자 오류');for(let k of ['volume','adjusted_close','sector_benchmark'])if(finite(r[k])&&(r[k]<0||(k!=='volume'&&r[k]===0)))throw Error(k+' 범위 오류');if(finite(r.foreign_ownership)&&(r.foreign_ownership<0||r.foreign_ownership>100))throw Error('외국인 보유율 범위 오류');if(r.events!==undefined&&(!Array.isArray(r.events)||r.events.some(e=>!e||typeof e.type!=='string'||typeof e.verified!=='boolean'||typeof e.source_url!=='string'||!/^https:\/\//.test(e.source_url))))throw Error('events 형식 또는 HTTPS 출처 오류');if(!groups.has(r.code))groups.set(r.code,[]);groups.get(r.code).push(r);}
if(meta.notes!==undefined&&(!Array.isArray(meta.notes)||meta.notes.some(n=>typeof n!=='string')))throw Error('notes는 문자열 배열이어야 합니다.');let dates=meta.trading_dates;if(input.rows.length&&(!Array.isArray(dates)||!dates.length||dates.some((d,i)=>!/^\d{4}-\d{2}-\d{2}$/.test(d)||(i&&d<=dates[i-1]))))throw Error('정렬된 공식 거래일 목록 trading_dates가 필요합니다.');for(let a of groups.values()){a.sort((x,y)=>x.date.localeCompare(y.date));if(a.some(r=>r.name!==a[0].name||r.sector!==a[0].sector))throw Error('동일 종목의 이름·업종이 다릅니다.');let exp=dates.filter(d=>d>=a[0].date&&d<=a.at(-1).date);if(exp.length!==a.length||a.some((r,i)=>r.date!==exp[i]))throw Error('거래일 누락: '+a[0].code);if(a.at(-1).date!==meta.as_of)throw Error('종목별 최종일과 as_of가 다릅니다.');}if(input.rows.length&&dates.at(-1)!==meta.as_of)throw Error('거래일 목록 최종일 오류');let bench=new Map();for(let r of input.rows){if(bench.has(r.date)&&bench.get(r.date)!==r.benchmark)throw Error('같은 날짜 KOSPI 지수가 다릅니다.');bench.set(r.date,r.benchmark);}if(meta.data_kind==='empty'&&input.rows.length)throw Error('빈 데이터에 행이 있습니다.');return{...input,groups:[...groups.values()]};}
export function parseCSV(text){let rows=[],row=[],cell='',quote=false;for(let i=0;i<text.length;i++){let c=text[i];if(c==='"'){if(quote&&text[i+1]==='"'){cell+='"';i++}else quote=!quote}else if(c===','&&!quote){row.push(cell);cell=''}else if(c==='\n'&&!quote){row.push(cell.replace(/\r$/,''));rows.push(row);row=[];cell=''}else cell+=c;}if(quote)throw Error('닫히지 않은 따옴표');if(cell||row.length){row.push(cell.replace(/\r$/,''));rows.push(row)}rows=rows.filter(r=>r.some(c=>c.trim()));let headers=rows.shift()?.map(s=>s.trim().replace(/^\ufeff/,''));if(!headers||new Set(headers).size!==headers.length)throw Error('CSV 헤더 오류');let strings=new Set(['date','code','name','sector','foreign_ownership_date','available_at']);return rows.map(r=>{if(r.length!==headers.length)throw Error('CSV 열 개수 오류');return Object.fromEntries(headers.map((k,i)=>[k,strings.has(k)?r[i].trim():(r[i].trim()===''?null:Number(r[i]))]));});}
